#!/usr/bin/env bash
# B3e = B3a with ONE factor changed: + --aug_snr_db 0 20 (default 5 20; SNR coupled group, --aug_snr_dist stays uniform; everything else identical to B3a, incl. --consistency js --consistency_lambda 0.3 --consistency_pairs both --batch_size 8, --aug_codec_profiles fixed)
#   generated by exploop (wave B3, iteration 5) from exploop/B3/iter05/design.result.json
#  B3e = B3a with one flag added: --aug_snr_db 0 20 (default 5 20). Every noise stage, MUSAN
#    included, now mixes its recording at a uniform SNR in 0..20 dB instead of 5..20 dB. The
#    distribution stays uniform, which leaves 0.750 of the noise draws in 5-20 dB; 0.150 of all
#    training views fall in 0-5 dB. Everything else is identical to B3a: - --consistency js
#    --consistency_lambda 0.3 --consistency_pairs both, --batch_size 8 = 8 pairs = 16 clips/step; -
#    8 epochs, LR 2.5e-6 warmup-cosine to 5e-7; - sampler shuffle, CE weights 0.1 0.9; - RTC aug +
#    MUSAN with fixed codec profiles, one stage per clip, loudness norm -23. It runs ~8 h. Evidence
#    (B3a merge_top5 metrics.json): - The sim eval sets draw SNR from {0, 5, 10, 15, 20}
#    (build_dev_noisy_sim.py), and training never went below 5 dB. - SNR 0 is the worst slice on
#    both sets, a step below 5 dB: matched F1 0.8615 vs 0.9034, R_bona 0.6581 vs 0.7712; heldout F1
#    0.8572 vs 0.9039, R_bona 0.6531 vs 0.7756. Spoof recall at 0 dB stays near 0.985. - SNR-0
#    clips are 0.178 / 0.203 of the matched / heldout sets. 40 of 123 half_B SNR-0 noisy bona are
#    false alarms (B3d report). - B3b (sampler, -0.83), B3c (lambda 1.0, -0.77) and B3d (random
#    codec, -2.20) ruled out exposure, more invariance on the same distribution, and moving
#    training off the eval distribution. This lever extends training onto the eval support instead.
#    Target: SNR-0 bona false alarms on matched and heldout. Rule against B3a-top5 = 93.06 on
#    half_B: promote if the delta is > +0.5, the CI excludes 0 and the clean drop is <= 0.5; null
#    within +-0.5; negative below -0.5.
#  Why: This is the last iteration (5 of max_iterations 5), so it gets the lever with the strongest
#    evidence that has not been tested yet. **Largest remaining error.** It is the B3d report's §7
#    "largest remaining error", also in the analysis JSON. It is B3a-top5's confident noisy bona
#    false alarms: 180 of 782 half_B noisy bona, 77 % of them at p >= 0.99. SNR 0 is the cleanest
#    single block of them, at 40 of 123 half_B SNR-0 noisy bona. **SNR 0 is outside the training
#    support** (derivation, computed from B3a merge_top5 metrics.json and the builder): - The sim
#    eval sets draw SNR equiprobably from SNR_GRID = (0, 5, 10, 15, 20). SNR-0 clips are 0.178 of
#    sim_matched_v1 and 0.203 of sim_heldout_v1. - Training draws only 5..20 dB. B3a's header reads
#    "SNR: 5..20 dB dist=uniform". - SNR 0 is the worst SNR slice on both sets by a step, not a
#    gradient: - matched F1 0.8615 at 0 dB vs 0.9034 at 5 dB; EER 0.1467 vs 0.1010; R_bona 0.6581
#    vs 0.7712; - heldout F1 0.8572 vs 0.9039; EER 0.1508 vs 0.1011; R_bona 0.6531 vs 0.7756. -
#    5..20 dB is fairly flat by comparison: matched F1 0.9034-0.9508, heldout 0.9039-0.9221. So the
#    cliff sits exactly where training stops. - The B2 wave summary already flagged this (C4: "SNR
#    0 is the worst slice on both sim sets ... and was never trained"). **What the wave has ruled
#    out:** - B3b (sampler, -0.83): exposure and the operating point. - B3c (lambda 1.0, -0.77):
#    more invariance on the same augmentation distribution. - B3d (random codec, -2.20): moving the
#    training distribution away from the eval distribution. The B3d analyst's lesson is to extend
#    training toward the eval support, never away from it. This lever does exactly that: it covers
#    an SNR the eval grid contains and leaves the codec table, noise pools, stage mix and
#    single-stage structure untouched. The noise families in the matched set are the training
#    pools, at an SNR the model has never seen. **The change is moderate** (derivation): - 0.600 of
#    training views get a noise stage. Under 0..20, 0.250 of those draws (0.150 of views) fall in
#    0-5 dB, and 0.750 stay in 5-20 dB. - The 15-20 dB share drops only from 0.333 to 0.250 of
#    noise draws. Mean SNR goes from 12.5 to 10.0 dB. - Compare B3d, where 0.600 of codec draws
#    moved to <= 12 kbps and every view's codec changed. **Constraints:** - One factor:
#    `--aug_snr_db`, inside the SNR coupled group. `--aug_snr_dist` stays uniform. - All flags are
#    in `allowed`; nothing forbidden or fixed is touched; 8 of max 10 epochs. - The consistency
#    group (js, 0.3, both, `--batch_size 8`) and `--ce_weights 0.1 0.9` are unchanged, so CE, JS
#    and dev loss stay directly comparable with B3a's per-epoch values. - The lever is in wave.json
#    lever_queue (`snr_0_20`). The plan notes that uniform keeps the high-SNR mass, whereas beta
#    mode 8 cut the >= 15 dB share in smoke, so uniform is kept. **Why not the alternatives:** -
#    SpecAugment (rank 2) targets over-fitting. The B3d report §5.5 found the wave's failures were
#    mismatch and difficulty, not over-fitting. B3a's dev loss rose while its mini WF1 still rose
#    through epoch 6. Masking also adds an input transformation the eval never sees. - `--llrd 0.9`
#    (rank 3) means moving the backbone less. The B2 LR series says that axis saturated between
#    5e-6 and 2.5e-6: "5e-6 and 2.5e-6 are equivalent on one seed", and the third halving changed
#    neither the epoch-1 state nor the plateau. So the expected gain is small. -
#    `--consistency_lambda 0.0` is a recipe control with no targeted error. - `--aug_max_stages 2`
#    repeats B3d's move away from the single-stage eval sim. - `--use_level_aug`: B3a's limiter
#    probe flips only 2.67 % of bona. - A seed repeat is not warranted while an evidence-backed
#    configuration lever remains.
#  Hypothesis: The SNR-0 bona false alarms are out-of-support inputs, not an inherently hard class
#    boundary. At 0 dB the noise has the same power as the speech. That masks the bona cues the
#    model learned at 5-20 dB, and with the spoof-leaning prior the model defaults to spoof. Spoof
#    recall at SNR 0 stays high (0.9865 matched / 0.9850 heldout) while bona recall collapses to
#    0.6581 / 0.6531. Training on 0-5 dB gives CE both bona and spoof examples at that level,
#    through the same noise pools, codecs and stages. A noise-level cue cannot become class-owned,
#    because both classes are mixed identically. The paired JS at 0.3 then asks two views of a
#    clip, each drawing its own SNR in 0..20, to agree. That widens the invariance range to cover
#    the full eval grid instead of adding weight on the same distribution (B3c) or shifting off it
#    (B3d). Expected effect: - SNR-0 bona recall and EER improve on matched and heldout, and SNR 5
#    should improve somewhat too. - 15-20 dB stays flat, because 0.750 of noise draws remain in
#    5-20 dB. - Spoof recall holds. - Since SNR 0 is ~18-20 % of the noisy sim clips, the set-level
#    matched and heldout F1 rise enough to lift the merge half_B WF1 above B3a's.
#  Expected signature: Merge vs B3a-top5 (half_B WF1 93.06); ep8 vs B3a-ep8 (92.94). Slice values
#    are full-set from metrics.json breakdowns.snr_db. **SNR 0:** - matched R_bona at least 3
#    points above 65.81 and EER below 14.67; - heldout R_bona at least 3 above 65.31 and EER below
#    15.08; - R_spoof within 0.5 of 98.65 / 98.50. **SNR 5:** matched / heldout EER at or below
#    10.10 / 10.11, R_bona not below 77.12 / 77.56. **SNR 15-20:** R_bona within 2 of B3a: matched
#    82.57 / 85.83, heldout 74.17 / 79.86. **Half_B false alarms (merge):** - SNR-0 noisy bona
#    false alarms below 40 of 123; - total noisy bona false alarms below 180 of 782; - noisy bona
#    share at p >= 0.99 not above 17.6 %. **Sets:** - matched and heldout half_B F1 up, with
#    heldout F1 above 90.20; - mean noisy EER below 9.16; - clean F1 within 0.5 of 97.48; - echo
#    within its noise band. Echo has no SNR axis, so any change there is indirect. **Per epoch:** -
#    epoch-1 train acc within 2 points of B3a's 90.16, and CE near B3a's 0.3945 (slightly higher is
#    expected); - epoch-8 CE below 1.5 x 0.0283; - mini WF1 not below B3a's at most epochs.
#    **Headline:** merge half_B WF1 above 93.06.
#  Derivation: python3 -I (stage list from the B3a nohup log header "stages=[coffee, footsteps,
#    keyboard, musan, office, rain, echo, reverb]", p_apply=0.8, one stage per clip, equal chance
#    1/8; echo / reverb draw no SNR; SNR grid of the sim eval sets from
#    scripts/build_dev_noisy_sim.py line 55 SNR_GRID = (0, 5, 10, 15, 20); slice values from B3a
#    merge_top5 metrics.json breakdowns.snr_db): share of training views with a noise stage: 0.600
#    SNR 5..20: noise draws in 0-5 dB 0.000 (of views 0.000); in 15-20 dB 0.333 (of views 0.200);
#    mean SNR 12.5 dB; noise draws in 5-20 dB 1.000 SNR 0..20: noise draws in 0-5 dB 0.250 (of
#    views 0.150); in 15-20 dB 0.250 (of views 0.150); mean SNR 10.0 dB; noise draws in 5-20 dB
#    0.750 sim_matched_v1 full-set clips 4000, SNR-0 clips 711 (0.178) B3a-top5 snr 0: f1 0.8615
#    eer 0.1467 R_bona 0.6581 R_spoof 0.9865 (n 711, bona 117) B3a-top5 snr 5: f1 0.9034 eer 0.1010
#    R_bona 0.7712 R_spoof 0.9851 (n 656, bona 118) B3a-top5 snr 10: f1 0.9180 eer 0.0741 R_bona
#    0.7661 R_spoof 0.9981 (n 653, bona 124) B3a-top5 snr 15: f1 0.9357 eer 0.0694 R_bona 0.8257
#    R_spoof 0.9946 (n 660, bona 109) B3a-top5 snr 20: f1 0.9508 eer 0.0635 R_bona 0.8583 R_spoof
#    0.9981 (n 642, bona 127) sim_heldout_v1 full-set clips 4000, SNR-0 clips 812 (0.203) B3a-top5
#    snr 0: f1 0.8572 eer 0.1508 R_bona 0.6531 R_spoof 0.9850 (n 812, bona 147) B3a-top5 snr 5: f1
#    0.9039 eer 0.1011 R_bona 0.7756 R_spoof 0.9839 (n 778, bona 156) B3a-top5 snr 10: f1 0.9113
#    eer 0.1029 R_bona 0.7829 R_spoof 0.9879 (n 815, bona 152) B3a-top5 snr 15: f1 0.9042 eer
#    0.0931 R_bona 0.7417 R_spoof 0.9942 (n 835, bona 151) B3a-top5 snr 20: f1 0.9221 eer 0.0898
#    R_bona 0.7986 R_spoof 0.9919 (n 760, bona 144) Code path check (SLS_setup/b3wave/augment.py):
#    - With max_stages 1 and snr_dist uniform, delegate_stage stays True, so the parent
#    RTCAugmenter._stage runs: add_noise(audio, ..., cfg.snr_db, sr), and cfg.snr_db = (0.0, 20.0)
#    comes from build_rtc_augmenter_b3. - The range therefore takes effect on every noise stage,
#    MUSAN included. Per-epoch SNR-bin telemetry is not counted on this path, so proof is the
#    header lines only. - train.py lines 626-628 print "SNR: 0..20 dB dist=uniform | Chaining:
#    max_stages=1 | Codec profiles: fixed". describe() prints "snr=0..20 dB" in the "RTC
#    augmentation:" line.
#  Eval note: Evaluate both readouts with --loudness_norm --loudness_norm_lufs -23 (read from
#    config.yaml): the top-5 merge (the objective) and epoch_8. Checkpoints are plain ModelSLS
#    state_dicts. Compare against B3a-top5 / B3a-ep8 (the current best) and the fixed comparators
#    B2f-top5 / B2f-ep8, with the paired-bootstrap CI at n 2000. Report: - **SNR slices:** full-set
#    breakdowns.snr_db for matched and heldout at 0 / 5 / 10 / 15 / 20 / (none): F1, EER, R_bona,
#    R_spoof against B3a-top5. Plus half_B noisy bona false alarms split by SNR (SNR 0 separately:
#    B3a-top5 40 of 123), by codec and by en / zh. - **Saturated tail and threshold:** the noisy
#    bona share at p >= 0.99 / 0.999, and the best global logit threshold. - **Set level:** mean
#    noisy EER, per-set R_bona / R_spoof, and clean F1. - **Probes:** noise_only / sil_only. They
#    are the closest probes to low-SNR bona. - **Per epoch vs B3a:** CE / JS / train acc and dev
#    loss (same CE weights, so directly comparable). Epoch-1 train acc and CE are the early
#    under-fit check, as in B3d. SNR-bin telemetry is not counted on this path (max_stages 1 with
#    uniform delegates to the parent augmenter), so the change is proven by the header lines. State
#    which of falsifiers 1-4 fired.
#  Falsification (pre-registered): delta top-5-merge half_B.wf1.wf1 vs B3a merge (93.06) > +0.5
#    with the paired-bootstrap CI excluding 0 and clean F1 drop <= 0.5 -> positive; within +-0.5 ->
#    null; below -0.5 -> negative. **Wave rule** against B3a-top5 = 93.06 on half_B: - promote /
#    positive: delta merge > +0.5, the paired-bootstrap CI excluding 0, and a clean F1 drop <= 0.5;
#    - null: delta within +-0.5; - negative: delta below -0.5. **Mechanism-level refutations:** 1.
#    **The SNR range is not the limit.** Delta within +-0.5 AND full-set SNR-0 R_bona within +-3 of
#    65.81 (matched) / 65.31 (heldout). The SNR-0 errors are not an out-of-support problem. 2.
#    **Covered, but traded away.** SNR-0 R_bona up >= 3 while 15-20 dB R_bona falls > 2 on matched
#    or heldout, or the clean drop is > 0.5. Spending a quarter of the noise draws below 5 dB cost
#    the high-SNR mass, and the net is null or negative. 3. **0 dB masks the spoof cue.** Full-set
#    SNR-0 R_spoof down > 0.5 from 98.65 / 98.50, or half_B R_spoof down > 0.5 on matched or
#    heldout. At 0 dB the synthesis artefacts are drowned, and training there teaches the model to
#    wave noisy spoof through. 4. **B3d-like under-fit: any harder training distribution hurts at
#    this budget.** Epoch-1 train acc more than 2 below 90.16, epoch-8 CE above 1.5 x 0.0283, and
#    every set down (R_bona down > 2 on the 15-20 dB slices). The recipe stays B3a, and
#    augmentation levers are closed for the full run.
#
#   bash scripts/run_B3e.sh                                   # fresh run (the exploop supervisor launches it)
#   bash scripts/run_B3e.sh --resume exp/<run dir name>       # after a container restart
#   EXPLOOP_PRINT_ARGV=1 bash scripts/run_B3e.sh              # print the trainer argv, launch nothing
#
# Rendered from scripts/exploop/launcher_template.sh (same shape as scripts/run_B3a.sh). Extra
# arguments are appended to the trainer command line. Training runs under nohup; stdout/stderr go to
# <workdir>/<track>_<timestamp>.log and the per-epoch summary to <run dir>/logs/train.log.
set -euo pipefail

PY="${PY:-/root/.conda/envs/rtc-sdd/bin/python}"
TRACK="B3e_qwen17_rtc_musan_loud23_cos8_lr2.5e6_cjs03_snr0to20_s1234"
WORKDIR="/root/repos/rtc-sdd/Ghostbusters_team/SLS_setup"

ARGS=(
    --train_data_path /mnt/paml-research/RTCFake/data/wav/train
    --train_protocol /mnt/paml-research/RTCFake/data/train_label.txt
    --dev_data_path /mnt/paml-research/RTCFake/data/wav/dev
    --dev_protocol ../data/dev_noisy_sim/dev_label_excl_halfB.txt
    --ssl_name Qwen/Qwen3-ASR-1.7B
    --n_layers 24
    --batch_size 8
    --num_epochs 8
    --num_workers 64
    --use_rtc_aug
    --aug_noise_dirs ../data/augmentation_train/rnnoise ../data/augmentation_train/esc50
    --aug_rir_dirs ../data/augmentation_train/rirs
    --musan
    --musan_dir ../data/augmentation/musan
    --loudness_norm
    --loudness_norm_lufs -23
    --optim adamw
    --lr 2.5e-6
    --head_lr_mult 10
    --weight_decay 0.01
    --lr_scheduler warmup_cosine
    --warmup_frac 0.05
    --lr_min 5e-7
    --grad_clip 1.0
    --ema_decay 0.9995
    --local_eval_sets ../configs/local_eval_sets.yaml
    --earlystop_metric wf1
    --earlystop_epoch 99
    --keep_topk_by_wf1 7
    --keep_epochs 8
    --seed 1234
    --track "$TRACK"
    --consistency js
    --consistency_lambda 0.3
    --consistency_pairs both
    --aug_snr_db 0 20
)

if [ "${EXPLOOP_PRINT_ARGV:-0}" = "1" ]; then
    printf '%s\n' "${ARGS[@]}"
    exit 0
fi

if [ ! -x "$PY" ]; then
    echo "python not found: $PY (set PY=... to override)" >&2
    exit 1
fi
if ! command -v ffmpeg >/dev/null 2>&1; then
    echo "ffmpeg not found on PATH: the RTC codec augmentation would silently no-op. Reinstall it first." >&2
    exit 1
fi
if ! "$PY" -c "import pyloudnorm" >/dev/null 2>&1; then
    echo "pyloudnorm not importable by $PY: run '$PY -m pip install pyloudnorm==0.2.0' first." >&2
    exit 1
fi

cd "$WORKDIR"
LOG="${TRACK}_$(date +%Y%m%d%H%M%S).log"

nohup "$PY" -u -m b3wave.train "${ARGS[@]}" "$@" > "$LOG" 2>&1 &

PID=$!
echo "Started $TRACK (pid $PID)"
echo "Log:     $WORKDIR/$LOG"
echo "Follow:  tail -f $WORKDIR/$LOG"
echo "Stop:    kill $PID"
